<script lang="ts">
 import {onMount} from 'svelte';
 import {DashboardApiError} from '../lib/api';
 import {nutritionApi as api,fmt,comparisonNutrients,carbExplanation,mealLabels,locationLabels,type Food,type Recipe,type Lot,type Diary,type Profile,type PlanEntry,type Shopping,type Energy,type Overview,type CookingPreview} from '../lib/nutritionApi';
 import NutritionProfile from './NutritionProfile.svelte';
 import CatalogEditor from './CatalogEditor.svelte';
 import NutritionCharts from './NutritionCharts.svelte';
 import NutritionTraining from '../analytics/NutritionTraining.svelte';
 let view=$state('overview'),active=$state(false),date=$state(''),loading=$state(false),busy=$state(false),error=$state(''),message=$state('');
 let foods=$state<Food[]>([]),recipes=$state<Recipe[]>([]),lots=$state<Lot[]>([]),profile=$state<Profile>({version:0}),diary=$state<Diary|null>(null),overview=$state<Overview|null>(null),plans=$state<PlanEntry[]>([]),lists=$state<Shopping[]>([]),days=$state<Diary[]>([]),energy=$state<Energy|null>(null);
 let history=$state<{id:string;operation_id:string;created_at:string;reason:string;delta:number;reversed_by:string|null}[]>([]);
 let foodEdit=$state<Food|null>(null),recipeEdit=$state<Recipe|null>(null),search=$state(''),recipeFilter=$state('');
 let receiptFood=$state(''),receiptQuantity=$state(''),receiptLocation=$state('pantry'),receiptExpiry=$state(''),receiptCost=$state(''),receiptDate=$state('');
 let logKind=$state('food'),logSource=$state(''),logQuantity=$state('1'),logMeal=$state('lunch'),logConsume=$state(false);
 let prepRecipe=$state(''),prepQuantity=$state(''),prepLocation=$state('fridge'),prepExpiry=$state(''),prepMass=$state('');
 let prepPreview=$state<(CookingPreview & {fingerprint:string})|null>(null);
 let prepOptionalPositions=$state<number[]>([]);
 let scale=$state<Record<string,{portions:string;factor:string;feasible:boolean;missing:{name:string;quantity:string}[];warnings:string[]}>>({});
 let planRecipe=$state(''),planDate=$state(''),planPortions=$state('1'),planMeal=$state('lunch');
 let schedule=$state<{id:string;planned_date:string;name:string;recipe_version_id:string;portions:number}[]>([]),planSummary=$state<{nutrients:Record<string,string|null>;estimatedCost:string|null;days:{date:string;nutrients:Record<string,string|null>}[]}|null>(null);
 let scheduleId=$state<string|null>(null),plannedPrepDate=$state(''),planEdit=$state<{id:string;version:number}|null>(null);
 let shoppingPreview=$state<{name:string;quantity:string;unit:string;cost:string|null;priceDate:string|null}[]|null>(null);
 let aiLots=$state<string[]>([]),aiPreview=$state<{previewId:string;items:{name:string;quantity:string;unit:string}[];staticInstructions:string}|null>(null),aiConfirmed=$state(false),aiDrafts=$state<{id:string;recipe:{name:string;steps:string[];ingredients:{foodId:string;quantity:string}[]}}[]>([]);
 let usdaQuery=$state(''),usdaResults=$state<{sourceId:string;name:string}[]>([]);
 let trainingMinutes=$state(''),extraCalories=$state(''),extraCarbs=$state('');
 let controller:AbortController|undefined,energyController:AbortController|undefined;
 const titles:Record<string,string>={overview:'Dnevni pregled prehrane',diary:'Dnevnik prehrane',planner:'Tjedni planer',recipes:'Recepti',prep:'Meal Prep',inventory:'Zalihe',shopping:'Kupovina'};
 function shift(day:string,n:number){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
 function weekStart(day:string){return shift(day,-((new Date(day+'T12:00:00Z').getUTCDay()+6)%7))}
 const options=$derived(logKind==='food'?foods.map(f=>({id:f.id,name:f.name,unit:f.unit})):logKind==='recipe'?recipes.map(r=>({id:r.versionId,name:r.name,unit:'porcija'})):lots.filter(l=>l.batch_id).map(l=>({id:l.id,name:`${l.name} · ${l.quantity} porcija`,unit:'porcija'})));
 const prepBody=$derived({recipeVersionId:prepRecipe,portions:prepQuantity,location:prepLocation,expiresOn:prepExpiry,asOf:date,cookedMass:prepMass||null,scheduleId,optionalIngredientPositions:[...prepOptionalPositions].sort((a,b)=>a-b)});
 const shownRecipes=$derived(recipes.filter(r=>r.name.toLocaleLowerCase('hr').includes(search.toLocaleLowerCase('hr'))&&(!recipeFilter||r.tags.includes(recipeFilter))));
 const nutritionTargets=$derived(diary?.targets??{});
 const comparableMacros=$derived(diary?comparisonNutrients(diary):null);
 const balance=$derived(
   diary?.date===date && energy?.date===date && diary.nutrients.kcal!=null && energy.totalCalories!=null
     ? Number(diary.nutrients.kcal)-energy.totalCalories : null
 );
 const allDays=$derived(date?Array.from({length:7},(_,i)=>shift(weekStart(date),i)):[]);
 async function load(){if(!active||!date)return;const requestedDate=date,revision=contextRevision;controller?.abort();controller=new AbortController();const signal=controller.signal;loading=true;error='';
 try{const [f,r,l,p,d,o,pl,sl,h,ds,sch,ps]=await Promise.all([api<Food[]>('/foods','GET',undefined,signal),api<Recipe[]>('/recipes','GET',undefined,signal),api<Lot[]>('/inventory','GET',undefined,signal),api<Profile>('/profile','GET',undefined,signal),api<Diary>(`/diary?date=${date}`,'GET',undefined,signal),api<Overview>(`/dashboard?date=${date}`,'GET',undefined,signal),api<PlanEntry[]>(`/plan?week=${weekStart(date)}`,'GET',undefined,signal),api<Shopping[]>('/shopping/lists','GET',undefined,signal),api<typeof history>('/inventory/history','GET',undefined,signal),api<Diary[]>(`/analytics?start=${shift(date,-6)}&end=${date}`,'GET',undefined,signal),api<typeof schedule>('/prep/schedule','GET',undefined,signal),api<NonNullable<typeof planSummary>>(`/plan/summary?week=${weekStart(date)}`,'GET',undefined,signal)]);if(signal.aborted||date!==requestedDate)return;
 if(d.date!==requestedDate){diary=null;throw new Error('Datum primljenog dnevnika ne odgovara odabranom danu. Osvježi prehranu.')}
 foods=f;recipes=r;lots=l;profile=p;if(!prepQuantity&&p.prepPortions)prepQuantity=String(p.prepPortions);diary=d;overview=o;plans=pl;lists=sl;history=h;days=ds;schedule=sch;planSummary=ps}
 catch(e){if(!signal.aborted&&revision===contextRevision)error=e instanceof Error?e.message:String(e)}finally{if(!signal.aborted)loading=false}}
 async function loadEnergy(){
   energyController?.abort();
   energy=null;
   if(!active||!date)return;
   const requestedDate=date;
   energyController=new AbortController();
   const signal=energyController.signal;
   const unavailable:Energy={date:requestedDate,status:'unavailable',source:'Garmin',fetchedAt:null,
     totalCalories:null,activeCalories:null,restingCalories:null,localEstimate:null,provisional:false};
   try{
     const result=await api<Energy>(`/energy?date=${requestedDate}`,'GET',undefined,signal);
     if(signal.aborted||date!==requestedDate)return;
     energy=result.date===requestedDate ? result : unavailable;
   }catch{
     if(!signal.aborted&&date===requestedDate)energy=unavailable;
   }
 }
 function refresh(){
   if(active){void load();void loadEnergy()}
 }
 let contextRevision=0;
 function clearNotices(){contextRevision++;error='';message=''}
 async function action(work:()=>Promise<unknown>,success='Promjena je spremljena.'){
  if(busy)return;
  const revision=contextRevision;
  busy=true;error='';message='';
  try{
   await work();
   if(revision===contextRevision){message=success;await load()}
  }catch(e){if(revision===contextRevision)error=e instanceof Error?e.message:String(e)}
  finally{busy=false}
 }
 async function previewShopping(){
  const revision=contextRevision;
  const start=weekStart(date),end=shift(start,6);
  await action(async()=>{
   const result=await api<NonNullable<typeof shoppingPreview>>('/shopping/preview','POST',{start,end});
   if(revision===contextRevision)shoppingPreview=result.filter(item=>Number(item.quantity)>0);
  },'Pregled manjka je spreman.');
 }
 function navigate(){const previousView=view,wasActive=active;const hash=location.hash;active=document.querySelector('main.shell')?.getAttribute('data-active-view')==='nutrition'||hash.startsWith('#nutrition-')||hash==='#view-nutrition';const next=hash.startsWith('#nutrition-')?hash.slice(11):'overview';view=next in titles?next:'overview';if(previousView!==view||wasActive!==active)clearNotices();if(active&&date&&(!diary||previousView!==view||!wasActive)){void load();if(energy?.date!==date)void loadEnergy()}}
 onMount(()=>{const input=document.getElementById('date') as HTMLInputElement;date=input.value;planDate=date;plannedPrepDate=date;navigate();const changed=()=>{clearNotices();date=input.value;planDate=date;plannedPrepDate=date;controller?.abort();energyController?.abort();energy=null;diary=null;days=[];prepPreview=null;shoppingPreview=null;refresh()};window.addEventListener('dashboard:navigation',navigate);window.addEventListener('popstate',navigate);input.addEventListener('change',changed);document.getElementById('refresh')?.addEventListener('click',refresh);return()=>{controller?.abort();energyController?.abort();window.removeEventListener('dashboard:navigation',navigate);window.removeEventListener('popstate',navigate);input.removeEventListener('change',changed);document.getElementById('refresh')?.removeEventListener('click',refresh)}});
 async function saveReceipt(e:SubmitEvent){e.preventDefault();await action(()=>api('/inventory/receipts','POST',{foodId:receiptFood,quantity:receiptQuantity,location:receiptLocation,expiresOn:receiptExpiry||null,cost:receiptCost||null,receivedOn:receiptDate||null}))}
 async function log(e:SubmitEvent){e.preventDefault();await action(()=>api('/diary/entries','POST',{date,meal:logMeal,kind:logKind,sourceId:logSource,quantity:logQuantity,consumeInventory:logConsume}),'Obrok je zabilježen uz nutritivni snapshot.')}
 async function lotAction(e:SubmitEvent,lot:Lot){e.preventDefault();const data=new FormData(e.currentTarget as HTMLFormElement);const kind=String(data.get('kind'));await action(()=>api(`/inventory/${kind}`,'POST',{lotId:lot.id,quantity:String(data.get('quantity')),reason:String(data.get('reason')),location:String(data.get('location')),expectedVersion:lot.version}))}
 async function purchase(e:SubmitEvent,item:Shopping['items'][number]){e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);await action(()=>api('/shopping/receive','POST',{itemId:item.id,quantity:String(f.get('quantity')),location:String(f.get('location')),expiresOn:String(f.get('expiresOn'))||null,cost:String(f.get('cost'))||null,expectedVersion:item.version,receivedOn:String(f.get('receivedOn'))||null}))}
 async function previewPrep(e:SubmitEvent){e.preventDefault();await action(async()=>{const result=await api<CookingPreview>('/prep/preview','POST',prepBody);prepPreview={...result,fingerprint:JSON.stringify(prepBody)}},'Provjeri sastojke, količine i rok prije potvrde kuhanja.')}

 async function commitPrep(){
  const body={...prepBody,previewToken:prepPreview?.previewToken};
  await action(async()=>{
   try{await api('/prep/batches','POST',body);prepPreview=null;scheduleId=null}
   catch(e){if(e instanceof DashboardApiError&&(e.status===409||e.status===422))prepPreview=null;throw e}
  },'Kuhanje je potvrđeno; gotove porcije su u zalihama.');
 }
 async function savePlan(e:SubmitEvent){e.preventDefault();await action(()=>api(planEdit?`/plan/entries/${planEdit.id}`:'/plan/entries',planEdit?'PATCH':'POST',{date:planDate,meal:planMeal,recipeVersionId:planRecipe,portions:planPortions,expectedVersion:planEdit?.version??1,status:plans.find(p=>p.id===planEdit?.id)?.status??'planned'}))}
 function sourceName(id:string){return foods.find(f=>f.id===id)?.name??'Namirnica'}
 function go(next:string){document.querySelector<HTMLAnchorElement>(`.quick-nav a[href="#nutrition-${next}"]`)?.click()}
 async function adaptive(){await action(()=>api(`/adaptive/apply?date=${date}`,'POST',{trainingLabel:energy?.nextRun?.title??'Vlastiti plan treninga',durationMinutes:Number(trainingMinutes),extraCalories:extraCalories||'0',extraCarbs:extraCarbs||'0',expectedVersion:profile.version}),'Prilagodba je potvrđena i spremljena od odabranog datuma.')}

</script>

<div class="nutrition" aria-busy={loading||busy}>
 <div class="nutrition-toolbar"><h2>{titles[view]}</h2><span class="badge">{date} · lokalna prehrana</span><button class="btn" onclick={refresh} disabled={loading}>Osvježi prehranu</button></div>
 {#if error}<div class="nutrition-notice error" role="alert">{error}</div>{/if}{#if message}<div class="nutrition-notice" role="status">{message}</div>{/if}
 {#if loading&&!diary}<div class="loading">Učitavam prehranu…</div>{/if}
 {#if active}
 <NutritionProfile {profile} {date} onchange={load}/>
 {#if view==='overview' && diary}
 <article class="hero-main nutrition-hero"><div class="eyebrow">DNEVNI UNOS · {diary.complete?'POTVRĐEN DAN':'DNEVNIK NIJE ZAKLJUČEN'}</div><h2>{fmt(diary.nutrients.kcal,0)} <small>kcal uneseno</small></h2><p>{profile.version?'Ciljevi i zabilježeni obroci za odabrani dan.':'Postavi svoj profil za usporedbu s ciljevima. Nema unaprijed zadanih vrijednosti.'}</p><div class="nutrition-actions"><button class="btn" onclick={()=>go('diary')}>Dodaj obrok</button><button class="btn" onclick={()=>go('planner')}>Otvori planer</button></div></article>
 <div class="nutrition-grid nutrition-kpis">
 <article class="panel"><h3>Energija</h3><strong class="nutrition-value">{fmt(diary.nutrients.kcal,0)} <small>kcal</small></strong><p>Cilj {fmt(nutritionTargets.calories,0)} kcal</p>{#if nutritionTargets.calories&&diary.nutrients.kcal!==null}<progress max="100" value={Math.min(100,Number(diary.nutrients.kcal)/Number(nutritionTargets.calories)*100)}></progress><p>{fmt(Number(diary.nutrients.kcal)/Number(nutritionTargets.calories)*100,0)}% cilja</p>{/if}</article>
 <article class="panel"><h3>Makronutrijenti</h3>{#each [['protein','Proteini'],['carbs','Ugljikohidrati'],['fat','Masti']] as [key,label]}<div class="nutrition-kv"><span>{label}</span><b>{fmt(comparableMacros?.[key as keyof typeof diary.nutrients])} / {fmt(nutritionTargets[key])} g</b></div>{/each}<p class="quiet">{carbExplanation(diary.carbComparison)}</p><p class="quiet">Vlakna {fmt(diary.nutrients.fiber)} g · energija prema izvornoj deklaraciji.</p></article>
 <article class="panel"><h3>Garmin energetski kontekst</h3><strong class="nutrition-value">{fmt(energy?.totalCalories,0)} <small>kcal ukupno</small></strong><p>Aktivno {fmt(energy?.activeCalories,0)} kcal · mirovanje {fmt(energy?.restingCalories,0)} kcal</p><p>Lokalna procjena punog dana: ≈{fmt(energy?.localEstimate,0)} kcal</p><p>Bilanca do sinkronizacije: {fmt(balance,0)} kcal</p><p class="quiet">{energy?.source??'Garmin'} · {energy?.date??date} · {energy==null?'Učitavanje':energy.totalCalories==null?'Nedostupno':energy.status==='partial'?'Djelomično':'Dostupno'} · {energy?.fetchedAt??'vrijeme nije dostupno'}. {diary.complete?'':'Dnevnik je nepotpun.'}</p></article>
 </div>
 <NutritionCharts {days} {energy}/>
 <NutritionTraining {date}/>
 <div class="nutrition-grid"><article class="panel"><h3>Današnji obroci</h3>{#each Object.entries(mealLabels) as [key,label]}<div class="nutrition-kv"><b>{label}</b><span>{diary.entries.filter(e=>e.meal===key).length} unosa · {overview?.meals.filter(e=>e.meal===key).length??0} planirano</span></div>{#each diary.entries.filter(e=>e.meal===key) as e}<p>{e.name} · {fmt(e.nutrients.kcal,0)} kcal · {fmt(e.nutrients.protein)} g proteina</p>{/each}{/each}<button class="btn" onclick={()=>go('diary')}>Otvori dnevnik</button></article>
 <article class="panel"><h3>Meal Prep i plan</h3><strong class="nutrition-value">{fmt(overview?.portions.reduce((s,l)=>s+Number(l.quantity),0)??0)} <small>gotovih porcija</small></strong><p>{overview?.meals.length??0} planiranih obroka danas</p><p>Sljedeća priprema: {schedule[0]?`${schedule[0].planned_date} · ${schedule[0].name}`:"nije planirana"}</p>{#if energy?.nextRun}<p>Sljedeći trening: {energy.nextRun.title} · {energy.nextRun.date??'datum prema Runna planu'}</p>{/if}<button class="btn" onclick={()=>go('prep')}>Pripremi unaprijed</button></article>
 <article class="panel nutrition-wide"><h3>Upozorenja zaliha</h3>{#each overview?.alerts??[] as l}<p>{l.name} · {l.quantity} {l.unit} · rok {l.expires_on}</p>{:else}<p class="quiet">Nema zabilježenih lotova s rokom u sljedeća 3 dana.</p>{/each}{#each overview?.lowStock??[] as f}<p>Niska zaliha: {f.name} · minimum {f.minimumQuantity} {f.unit}</p>{/each}<div class="nutrition-actions"><button class="btn" onclick={()=>go('inventory')}>Zalihe i AI pomoćnik</button><button class="btn" onclick={()=>go('shopping')}>Kupovina</button></div></article></div>
 {:else if view==='inventory'}
 <p class="quiet">Trenutačno stanje zaliha, ne povijesno stanje na datum pregleda. Planiranje ne oduzima zalihe.</p>
 <details class="panel nutrition-details" open={Boolean(foodEdit)}><summary>{foodEdit?'Uredi namirnicu':'Nova namirnica'}</summary><CatalogEditor mode="food" {foods} food={foodEdit} onchange={async()=>{foodEdit=null;await load()}}/></details>
 <details class="panel nutrition-details"><summary>Provjereni nutritivni izvori · USDA</summary><form class="nutrition-form" onsubmit={(e)=>{e.preventDefault();void action(async()=>{usdaResults=await api(`/food-search?q=${encodeURIComponent(usdaQuery)}`)},'Odaberi točan zapis; podaci se automatski ne zamjenjuju.')}}><label>Pretraži USDA<input required minlength="2" bind:value={usdaQuery}/></label><button class="btn" disabled={busy}>Pretraži vanjski izvor</button></form>{#each usdaResults as item}<div class="nutrition-row"><span>{item.name} · FDC {item.sourceId}</span><button class="btn" disabled={busy} onclick={()=>action(()=>api('/food-imports','POST',{sourceId:Number(item.sourceId),state:'label',confirmed:true}),'Namirnica je uvezena na osnovici /100 g; provjeri stanje i alergene u katalogu.')}>Potvrdi uvoz /100 g</button></div>{/each}</details>
 <article class="panel"><h3>Prijem namirnica</h3><form class="nutrition-form" onsubmit={saveReceipt}><div class="nutrition-fields"><label>Namirnica<select required bind:value={receiptFood}><option value="">Odaberi</option>{#each foods as f}<option value={f.id}>{f.name} · {f.unit}</option>{/each}</select></label><label>Količina<input required inputmode="decimal" bind:value={receiptQuantity}/></label><label>Lokacija<select bind:value={receiptLocation}>{#each Object.entries(locationLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label><label>Datum stvarnog primitka<input type="date" bind:value={receiptDate}/></label><label>Rok<input type="date" bind:value={receiptExpiry}/></label><label>Nabavna cijena ukupno · EUR<input inputmode="decimal" bind:value={receiptCost} placeholder="Nepoznato"/></label></div><button class="btn" disabled={busy}>Potvrdi prijem</button></form></article>
 <div class="nutrition-grid">{#each lots as lot}<article class="panel"><h3>{lot.name}</h3><strong class="nutrition-value">{lot.quantity} <small>{lot.unit}</small></strong><p>{locationLabels[lot.location]} · rok {lot.expires_on??'nije zadan'}</p><p>Raspoloživo {lot.availableQuantity??'—'} {lot.unit} · isteklo {lot.expiredQuantity??'—'} {lot.unit}</p><p class="quiet">Primitak ili priprema {lot.receivedOn??'datum nije poznat; zaliha je isključena iz raspoloživosti'}</p><details><summary>Otpad, premještanje ili korekcija</summary><form class="nutrition-form" onsubmit={(e)=>lotAction(e,lot)}><label>Operacija<select name="kind"><option value="waste">Otpad</option><option value="transfers">Premjesti količinu</option><option value="adjustments">Postavi ispravno stanje</option></select></label><label>Količina<input name="quantity" required inputmode="decimal"/></label><label>Lokacija<select name="location">{#each Object.entries(locationLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label><label>Razlog<input name="reason" required maxlength="300"/></label><button class="btn" disabled={busy}>Potvrdi promjenu</button></form></details></article>{:else}<article class="panel"><p class="quiet">Nema zaliha. Dodaj namirnicu i evidentiraj prijem.</p></article>{/each}</div>
 <details class="panel nutrition-details"><summary>Katalog namirnica · {foods.length}</summary>{#each foods as f}<div class="nutrition-row"><span>{f.name} · {f.state} · {f.source} · {f.retrievedAt??"datum izvora nije dostupan"}</span><button class="btn" onclick={()=>foodEdit=f}>Uredi</button></div>{/each}</details>
 <details class="panel nutrition-details"><summary>Povijest inventara</summary>{#each history as h}<div class="nutrition-row"><span>{h.created_at} · {h.reason} · {fmt(h.delta/1000)}</span><button class="btn" disabled={busy||Boolean(h.reversed_by)} onclick={()=>action(()=>api(`/operations/${h.operation_id}/reverse`,'POST'))}>Poništi operaciju</button></div>{/each}</details>
 <article class="panel"><h3>AI Recipe Assistant</h3><p class="quiet">Odaberi namirnice. Prije slanja prikazat će se točan sadržaj zahtjeva. AI budžet postavljaš u profilu.</p>{#each lots.filter(l=>l.food_id) as l}<label class="nutrition-check"><input type="checkbox" value={l.id} bind:group={aiLots} onchange={()=>{aiPreview=null;aiConfirmed=false}}/>{l.name} · {l.quantity} {l.unit} · {l.expires_on??'bez roka'}</label>{/each}<button class="btn" disabled={busy||!aiLots.length} onclick={()=>action(async()=>{aiPreview=await api('/ai/preview','POST',{lotIds:aiLots});aiConfirmed=false},'Pregledaj namirnice prije potvrde.')}>Prikaži sadržaj za slanje</button>
 {#if aiPreview}<div class="nutrition-notice"><h4>OpenAI-ju se šalje</h4>{#each aiPreview.items as i}<p>{i.name} · {i.quantity} {i.unit}</p>{/each}<details><summary>Statičke upute</summary><p>{aiPreview.staticInstructions}</p></details><label class="nutrition-check"><input type="checkbox" bind:checked={aiConfirmed}/>Potvrđujem slanje prikazanih naziva i količina OpenAI-ju</label><button class="btn" disabled={busy||!aiConfirmed} onclick={()=>action(async()=>{const result=await api<{drafts:typeof aiDrafts}>('/ai/generate','POST',{previewId:aiPreview!.previewId,confirmation:true});aiDrafts=result.drafts},'Prijedlozi su spremni za pregled.')}>Generiraj recepte</button></div>{/if}
 {#each aiDrafts as draft}<details class="nutrition-notice"><summary>{draft.recipe.name}</summary>{#each draft.recipe.ingredients as i}<p>{sourceName(i.foodId)} · {i.quantity}</p>{/each}<ol>{#each draft.recipe.steps as s}<li>{s}</li>{/each}</ol><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/ai/drafts/${draft.id}/save`,'POST'))}>Spremi recept lokalno</button></details>{/each}</article>
 {:else if view==='recipes'}
 <div class="nutrition-fields"><label>Pretraži recepte<input type="search" bind:value={search}/></label><label>Prehrambena oznaka<input bind:value={recipeFilter} placeholder="Prazno za sve"/></label></div>
 <details class="panel nutrition-details" open={Boolean(recipeEdit)}><summary>{recipeEdit?'Uredi recept':'Novi recept'}</summary><CatalogEditor mode="recipe" {foods} recipe={recipeEdit} onchange={async()=>{recipeEdit=null;await load()}}/>{#if recipeEdit}<button class="btn" onclick={()=>recipeEdit=null}>Završi uređivanje</button>{/if}</details>
 <div class="nutrition-grid">{#each shownRecipes as r}<article class="panel"><h3>{r.name}</h3><p>{r.portions} porcija · {r.minutes} min · {r.method}</p><p>{fmt(r.perPortion.kcal,0)} kcal · {fmt(r.perPortion.protein)} g proteina / porcija · {fmt(r.costPerPortion,2)} EUR</p><p class="quiet">{r.nutritionComplete?'Nutritivni podaci dostupni':'Nutritivni podaci nepotpuni'} · cijena prema zabilježenim nabavama</p><details><summary>Sastojci, izvori cijena i priprema</summary>{#each r.priceSources??[] as source}<p class="quiet">Nabavna cijena: {source.name} · {source.date}</p>{/each}{#each r.ingredients as i}<p>{sourceName(i.foodId)} · {i.quantity} {foods.find(f=>f.id===i.foodId)?.unit}</p>{/each}<ol>{#each r.steps as s}<li>{s}</li>{/each}</ol></details><div class="nutrition-actions"><button class="btn" onclick={()=>recipeEdit=r}>Uredi</button><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/recipes/${r.id}/duplicate`,'POST'))}>Dupliciraj</button><button class="btn" onclick={()=>{scheduleId=null;prepRecipe=r.versionId;prepQuantity=r.portions;go('prep')}}>Meal Prep</button><button class="btn" onclick={()=>{planRecipe=r.versionId;go('planner')}}>Planiraj</button></div>
 <form class="nutrition-form" onsubmit={(e)=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);void action(async()=>{scale[r.id]=await api(`/recipes/${r.id}/scale-preview`,'POST',{portions:String(f.get('portions'))||null,byInventory:f.get('byInventory')==='on',asOf:date})},'Skaliranje je pregled, original je sačuvan.')}}><label>Željene porcije<input name="portions" inputmode="decimal" value={r.portions}/></label><label class="nutrition-check"><input type="checkbox" name="byInventory"/>Najveći broj porcija prema zalihama</label><button class="btn" disabled={busy}>Pregled skaliranja</button></form>{#if scale[r.id]}<p>{scale[r.id].portions} porcija · faktor {scale[r.id].factor} · {scale[r.id].feasible?'izvedivo':'nedostaju sastojci'}</p>{#each scale[r.id].missing as m}<p>{m.name}: nedostaje {m.quantity}</p>{/each}{/if}</article>{:else}<article class="panel">Nema recepata za ovaj filtar.</article>{/each}</div>
 {:else if view==='prep'}
 <article class="panel"><h3>Priprema unaprijed</h3><p class="quiet">Provjera ne mijenja zalihe. Potvrđeno kuhanje oduzima sirove sastojke i stvara gotove porcije.</p><form class="nutrition-form" onsubmit={previewPrep}><div class="nutrition-fields"><label>Recept<select required bind:value={prepRecipe} onchange={()=>{prepOptionalPositions=[];prepPreview=null}}><option value="">Odaberi</option>{#each recipes as r}<option value={r.versionId}>{r.name}</option>{/each}</select></label><label>Porcije<input required inputmode="decimal" bind:value={prepQuantity}/></label><label>Gotova masa · g<input inputmode="decimal" bind:value={prepMass} placeholder="Izmjerena, opcionalno"/></label><label>Lokacija<select bind:value={prepLocation}>{#each Object.entries(locationLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label><label>Rok gotovog jela<input type="date" required bind:value={prepExpiry}/></label></div>{#each recipes.find(r=>r.versionId===prepRecipe)?.ingredients??[] as ingredient,position}{#if ingredient.optional}<label class="nutrition-check"><input type="checkbox" value={position} bind:group={prepOptionalPositions}/>Uključi opcionalni sastojak · {sourceName(ingredient.foodId)}</label>{/if}{/each}<p class="quiet">Isključeni opcionalni sastojci izostaju iz potrošnje i kalorija. Najmanja količina je 0,001 inventarne jedinice.</p><button class="btn" disabled={busy}>Provjeri pripremu</button></form>
 {#if prepPreview}<div class="nutrition-notice"><p>{prepPreview.portions} porcija · {prepPreview.feasible?'sastojci su dostupni':'pregled nije spreman za potvrdu'}</p>{#each prepPreview.issues as issue}<p>{issue.message}</p>{/each}{#each prepPreview.warnings as warning}<p>{warning}</p>{/each}{#each prepPreview.ingredients as ingredient}<p>{ingredient.name} · {ingredient.quantity} {ingredient.unit}</p>{/each}<p>{fmt(prepPreview.nutrients.kcal,0)} kcal · proteini {fmt(prepPreview.nutrients.protein)} g · UH {fmt(prepPreview.nutrients.carbs)} g · masti {fmt(prepPreview.nutrients.fat)} g</p><p>Trošak utrošenih zaliha {fmt(prepPreview.cost,2)} EUR · masa po porciji {fmt(prepPreview.massPerPortion)} g</p>{#each prepPreview.missing as m}<p>{m.name}: {m.quantity}</p>{/each}<button class="btn" disabled={busy||!prepPreview.feasible||prepPreview.fingerprint!==JSON.stringify(prepBody)} onclick={commitPrep}>Potvrdi kuhanje i potrošnju sastojaka</button></div>{/if}</article>
 <article class="panel"><h3>Raspored pripreme · 3, 5 ili 7 dana</h3><p class="quiet">Odaberi recept i broj porcija u gornjem obrascu. Zakazivanje ne troši sastojke.</p><label>Planirani datum pripreme<input type="date" bind:value={plannedPrepDate}/></label><button class="btn" disabled={busy||!prepRecipe||!prepQuantity||!plannedPrepDate} onclick={()=>action(()=>api('/prep/schedule','POST',{plannedDate:plannedPrepDate,recipeVersionId:prepRecipe,portions:prepQuantity}))}>Zakaži pripremu</button>{#each schedule as item}<div class="nutrition-row"><span>{item.planned_date} · {item.name} · {fmt(item.portions/1000)} porcija</span><button class="btn" onclick={()=>{prepOptionalPositions=[];scheduleId=item.id;prepRecipe=item.recipe_version_id;prepQuantity=String(item.portions/1000);prepPreview=null}}>Odaberi za kuhanje</button><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/prep/schedule/${item.id}`,'DELETE'))}>Otkaži plan</button></div>{/each}</article>
 <div class="nutrition-grid">{#each lots.filter(l=>l.batch_id) as l}<article class="panel"><h3>{l.name}</h3><p>{l.quantity} porcija · {locationLabels[l.location]} · rok {l.expires_on}</p><button class="btn" onclick={()=>{logKind='portion';logSource=l.id;go('diary')}}>Zabilježi konzumaciju</button></article>{:else}<article class="panel">Nema gotovih porcija.</article>{/each}</div>
 {:else if view==='diary' && diary}
 <article class="panel"><h3>Dodaj obrok</h3><form class="nutrition-form" onsubmit={log}><div class="nutrition-fields"><label>Vrsta<select bind:value={logKind} onchange={()=>{logSource='';logConsume=false}}><option value="food">Namirnica</option><option value="recipe">Recept · samo evidencija</option><option value="portion">Gotova porcija · potrošnja</option></select></label><label>Odaberi<select required bind:value={logSource}><option value="">Odaberi</option>{#each options as o}<option value={o.id}>{o.name}</option>{/each}</select></label><label>Količina · {options.find(o=>o.id===logSource)?.unit??'jedinica'}<input required inputmode="decimal" bind:value={logQuantity}/></label><label>Obrok<select bind:value={logMeal}>{#each Object.entries(mealLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label></div>{#if logKind==='food'}<label class="nutrition-check"><input type="checkbox" bind:checked={logConsume}/>Potroši iz inventara prema FEFO redoslijedu</label>{/if}<button class="btn" disabled={busy}>Potvrdi unos</button></form></article>
 <article class="panel"><h3>Unosi · {date}</h3>{#each diary.entries as e}<div class="nutrition-row"><div><b>{e.name}</b><p>{mealLabels[e.meal]} · {e.quantity} {e.unit} · {fmt(e.nutrients.kcal,0)} kcal · {fmt(e.nutrients.protein)} g proteina</p></div><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/operations/${e.operation_id}/reverse`,'POST'),'Unos je poništen kompenzacijom povezanog inventara.')}>Poništi unos</button></div>{:else}<p>Nema zabilježenih obroka. To nije potvrđen unos od nula kalorija.</p>{/each}<p>Izvorni zbroj {fmt(diary.nutrients.kcal,0)} kcal · proteini {fmt(diary.nutrients.protein)} g · UH {fmt(diary.nutrients.carbs)} g · masti {fmt(diary.nutrients.fat)} g</p><p>UH za usporedbu s ciljem {fmt(comparableMacros?.carbs)} g · {carbExplanation(diary.carbComparison)}</p><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/diary/days/${date}`,'PUT',{complete:!diary!.complete}))}>{diary.complete?'Ponovno otvori dan':'Potvrdi da je dnevnik za dan potpun'}</button></article>
 {:else if view==='planner'}
 <article class="panel"><h3>Dodaj planirani obrok</h3><form class="nutrition-form" onsubmit={savePlan}><div class="nutrition-fields"><label>Datum<input type="date" required bind:value={planDate}/></label><label>Obrok<select bind:value={planMeal}>{#each Object.entries(mealLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label><label>Recept<select required bind:value={planRecipe}><option value="">Odaberi</option>{#each recipes as r}<option value={r.versionId}>{r.name}</option>{/each}</select></label><label>Porcije<input required inputmode="decimal" bind:value={planPortions}/></label></div><button class="btn" disabled={busy}>{planEdit?"Spremi izmjenu plana":"Dodaj u plan"}</button>{#if planEdit}<button type="button" class="btn" onclick={()=>planEdit=null}>Završi uređivanje plana</button>{/if}</form></article>
 <article class="panel"><h3>Planirani tjedni zbroj</h3><p>{fmt(planSummary?.nutrients.kcal,0)} kcal · {fmt(planSummary?.nutrients.protein)} g proteina · procjena troška {fmt(planSummary?.estimatedCost,2)} EUR</p><p class="quiet">Nepoznate hranjive vrijednosti i cijene ostaju nepotpune. Ovaj zbroj opisuje plan.</p></article><div class="nutrition-week">{#each allDays as d}<article class="panel"><h3>{new Date(d+'T12:00:00').toLocaleDateString('hr-HR',{weekday:'short',day:'numeric',month:'numeric'})}</h3><p class="quiet">Planirano {fmt(planSummary?.days.find(day=>day.date===d)?.nutrients.kcal,0)} kcal</p>{#each plans.filter(p=>p.entry_date===d) as p}<div class="nutrition-plan-item"><b>{mealLabels[p.meal]} · {p.name}</b><label>Status plana<select value={p.status} disabled={busy} onchange={(e)=>action(()=>api(`/plan/entries/${p.id}`,'PATCH',{date:p.entry_date,meal:p.meal,recipeVersionId:p.recipe_version_id,portions:p.portions,expectedVersion:p.version,status:e.currentTarget.value}))}><option value="planned">Planirano</option><option value="prepared">Pripremljeno</option><option value="consumed">Konzumirano</option><option value="skipped">Preskočeno</option></select></label><p class="quiet">Status je oznaka plana; stvarnu potrošnju evidentiraj u Meal Prep ili Dnevniku.</p><p>{p.portions} porcija · {fmt(p.nutrients.kcal,0)} kcal · {fmt(p.nutrients.protein)} g proteina</p><div class="nutrition-actions"><button class="btn" onclick={()=>{planEdit={id:p.id,version:p.version};planRecipe=p.recipe_version_id;planPortions=p.portions;planMeal=p.meal;planDate=d}}>Uredi / premjesti</button><button class="btn" onclick={()=>{planEdit=null;planRecipe=p.recipe_version_id;planPortions=p.portions;planMeal=p.meal;planDate=shift(d,1)}}>Kopiraj na sljedeći dan</button><button class="btn" disabled={busy} onclick={()=>action(()=>api(`/plan/entries/${p.id}`,'DELETE'))}>Ukloni plan</button></div></div>{:else}<p class="quiet">Nema plana.</p>{/each}</article>{/each}</div>
 <details class="panel nutrition-details"><summary>Sportska prehrana · tvoja pravila</summary><p class="quiet">Sljedeći trening: {energy?.nextRun?.title??'nije dostupan'}. Ovdje sam određuješ prilagodbu; ne izračunava se iz aktivnih kalorija.</p><form class="nutrition-form" onsubmit={(e)=>{e.preventDefault();void adaptive()}}><label>Planirano trajanje · min<input required inputmode="numeric" bind:value={trainingMinutes}/></label><label>Tvoj dodatni kalorijski cilj · kcal<input required inputmode="decimal" bind:value={extraCalories}/></label><label>Tvoj dodatni cilj UH · g<input required inputmode="decimal" bind:value={extraCarbs}/></label><p>Prilagodba se sprema od {date}. Trajanje {trainingMinutes||'nije zadano'} min služi kao tvoj kontekst.</p><button class="btn" disabled={busy}>Potvrdi i spremi prilagođene ciljeve</button></form></details>
 {:else if view==='shopping'}
 <article class="panel"><h3>Kupovina iz tjednog plana</h3><p>{weekStart(date)} — {shift(weekStart(date),6)}. Manjkovi uključuju raspoložive sirove namirnice i gotove porcije do datuma uporabe.</p><button class="btn" disabled={busy} onclick={previewShopping}>Izračunaj manjkove</button>{#if shoppingPreview!==null}{#if shoppingPreview.length===0}<p>{plans.length===0?'Tjedni plan je prazan. Nema izračunatih stavki za kupnju.':'Za odabrani plan nema izračunatih manjkova.'}</p><p class="quiet">Možeš izraditi praznu listu i ručno dodati namirnice.</p>{/if}{#each shoppingPreview as i}<p>{i.name}: nedostaje {i.quantity} {i.unit} · {fmt(i.cost,2)} EUR · cijena {i.priceDate??'nepoznata'}</p>{/each}<button class="btn" disabled={busy} onclick={()=>action(()=>api('/shopping/lists','POST',{start:weekStart(date),end:shift(weekStart(date),6)}))}>{shoppingPreview.length?'Spremi novu listu':'Izradi praznu listu'}</button>{/if}</article>
 {#each lists as list}<article class="panel"><h3>{list.name}</h3><details><summary>Ručno dodaj namirnicu</summary><form class="nutrition-form" onsubmit={(e)=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);void action(()=>api(`/shopping/lists/${list.id}/items`,'POST',{foodId:String(f.get('foodId')),quantity:String(f.get('quantity')),packageSize:String(f.get('packageSize'))||null}))}}><label>Namirnica<select name="foodId" required><option value="">Odaberi</option>{#each foods as f}<option value={f.id}>{f.name} · {f.unit}</option>{/each}</select></label><label>Količina<input name="quantity" required inputmode="decimal"/></label><label>Veličina pakiranja<input name="packageSize" inputmode="decimal"/></label><button class="btn" disabled={busy}>Dodaj na listu</button></form></details>{#each list.items as item}<details class="nutrition-notice"><summary>{item.name} · {item.quantity} {item.unit} · {item.received?'zaprimljeno':item.checked?'kupljeno':'za kupnju'}</summary>
 {#if !item.received}<form class="nutrition-form" onsubmit={(e)=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);void action(()=>api(`/shopping/items/${item.id}`,'PATCH',{quantity:String(f.get('quantity')),packageSize:String(f.get('packageSize'))||null,checked:f.get('checked')==='on',expectedVersion:item.version,receivedOn:String(f.get('receivedOn'))||null}))}}><label>Potrebna količina<input name="quantity" value={item.quantity} required inputmode="decimal"/></label><label>Veličina pakiranja<input name="packageSize" value={item.packageSize??''} inputmode="decimal"/></label>{#if item.packageSize}<p>Pakiranja: {Math.ceil(Number(item.quantity)/Number(item.packageSize))}</p>{/if}<label class="nutrition-check"><input type="checkbox" name="checked" checked={item.checked}/>Kupljeno (još ne mijenja inventar)</label><button class="btn" disabled={busy}>Spremi stavku</button></form>
 <details><summary>Zaprimi kupljeno u inventar</summary><form class="nutrition-form" onsubmit={(e)=>purchase(e,item)}><label>Datum stvarnog primitka<input type="date" name="receivedOn"/></label><label>Stvarno primljena količina<input name="quantity" value={item.quantity} required inputmode="decimal"/></label><label>Lokacija<select name="location">{#each Object.entries(locationLabels) as [k,l]}<option value={k}>{l}</option>{/each}</select></label><label>Rok<input type="date" name="expiresOn"/></label><label>Ukupna cijena · EUR<input name="cost" inputmode="decimal"/></label><button class="btn" disabled={busy}>Potvrdi prijem u inventar</button></form></details>{/if}</details>{/each}</article>{:else}<article class="panel">Nema spremljenih lista. Izračunaj manjkove iz plana ili izradi praznu listu za ručni unos.</article>{/each}
 {/if}
 {/if}
</div>
